ALTER TABLE partners ADD COLUMN tax_code TEXT NOT NULL DEFAULT '';
ALTER TABLE partners ADD COLUMN address TEXT NOT NULL DEFAULT '';
DROP TRIGGER audit_capture_partners_insert;
DROP TRIGGER audit_capture_partners_update;
DROP TRIGGER audit_capture_partners_delete;
CREATE TRIGGER audit_capture_partners_insert AFTER INSERT ON partners WHEN EXISTS(SELECT 1 FROM audit_context) BEGIN INSERT INTO audit_changes(audit_id,table_name,row_key,before_state,after_state) SELECT audit_id,'partners',json_array(CAST(NEW.id AS TEXT)),NULL,json_object('id',CAST(NEW.id AS TEXT),'code',CAST(NEW.code AS TEXT),'name',CAST(NEW.name AS TEXT),'role',CAST(NEW.role AS TEXT),'email',CAST(NEW.email AS TEXT),'phone',CAST(NEW.phone AS TEXT),'active',CAST(NEW.active AS TEXT),'tax_code',CAST(NEW.tax_code AS TEXT),'address',CAST(NEW.address AS TEXT)) FROM audit_context WHERE id=1 ON CONFLICT(audit_id,table_name,row_key) DO UPDATE SET after_state=excluded.after_state; END;
CREATE TRIGGER audit_capture_partners_update AFTER UPDATE ON partners WHEN EXISTS(SELECT 1 FROM audit_context) AND json_object('id',CAST(OLD.id AS TEXT),'code',CAST(OLD.code AS TEXT),'name',CAST(OLD.name AS TEXT),'role',CAST(OLD.role AS TEXT),'email',CAST(OLD.email AS TEXT),'phone',CAST(OLD.phone AS TEXT),'active',CAST(OLD.active AS TEXT),'tax_code',CAST(OLD.tax_code AS TEXT),'address',CAST(OLD.address AS TEXT)) IS NOT json_object('id',CAST(NEW.id AS TEXT),'code',CAST(NEW.code AS TEXT),'name',CAST(NEW.name AS TEXT),'role',CAST(NEW.role AS TEXT),'email',CAST(NEW.email AS TEXT),'phone',CAST(NEW.phone AS TEXT),'active',CAST(NEW.active AS TEXT),'tax_code',CAST(NEW.tax_code AS TEXT),'address',CAST(NEW.address AS TEXT)) BEGIN INSERT INTO audit_changes(audit_id,table_name,row_key,before_state,after_state) SELECT audit_id,'partners',json_array(CAST(NEW.id AS TEXT)),json_object('id',CAST(OLD.id AS TEXT),'code',CAST(OLD.code AS TEXT),'name',CAST(OLD.name AS TEXT),'role',CAST(OLD.role AS TEXT),'email',CAST(OLD.email AS TEXT),'phone',CAST(OLD.phone AS TEXT),'active',CAST(OLD.active AS TEXT),'tax_code',CAST(OLD.tax_code AS TEXT),'address',CAST(OLD.address AS TEXT)),json_object('id',CAST(NEW.id AS TEXT),'code',CAST(NEW.code AS TEXT),'name',CAST(NEW.name AS TEXT),'role',CAST(NEW.role AS TEXT),'email',CAST(NEW.email AS TEXT),'phone',CAST(NEW.phone AS TEXT),'active',CAST(NEW.active AS TEXT),'tax_code',CAST(NEW.tax_code AS TEXT),'address',CAST(NEW.address AS TEXT)) FROM audit_context WHERE id=1 ON CONFLICT(audit_id,table_name,row_key) DO UPDATE SET after_state=excluded.after_state; END;
CREATE TRIGGER audit_capture_partners_delete AFTER DELETE ON partners WHEN EXISTS(SELECT 1 FROM audit_context) BEGIN INSERT INTO audit_changes(audit_id,table_name,row_key,before_state,after_state) SELECT audit_id,'partners',json_array(CAST(OLD.id AS TEXT)),json_object('id',CAST(OLD.id AS TEXT),'code',CAST(OLD.code AS TEXT),'name',CAST(OLD.name AS TEXT),'role',CAST(OLD.role AS TEXT),'email',CAST(OLD.email AS TEXT),'phone',CAST(OLD.phone AS TEXT),'active',CAST(OLD.active AS TEXT),'tax_code',CAST(OLD.tax_code AS TEXT),'address',CAST(OLD.address AS TEXT)),NULL FROM audit_context WHERE id=1 ON CONFLICT(audit_id,table_name,row_key) DO UPDATE SET after_state=excluded.after_state; END;
